using System;
using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;

/// <summary>
/// Builds the Android player from the command line.
///
/// Exists so a change can be put on a real phone without opening the editor, and
/// more to the point so the thing that is tested is the thing that was built - a
/// build made by hand between two edits is a build nobody can reproduce.
///
/// It runs the UI builder first. Everything under the Canvas is generated by
/// <see cref="AppUIBuilder"/>, so a player built without that step ships whatever
/// the scene happened to be saved with, which is how a fix reaches a phone and
/// appears not to work.
/// </summary>
public static class BuildApk
{
    const string Scene = "Assets/Scenes/Main.unity";
    const string OutputFolder = "Build";

    [MenuItem("Tools/Build/Android APK")]
    public static void Build()
    {
        string path = Path.Combine(OutputFolder, "ARTrail.apk");
        Directory.CreateDirectory(OutputFolder);

        // The scene on disk is generated output. Rebuilding it here is what keeps
        // "it compiles" and "it is in the player" from being different claims.
        EditorSceneManager.OpenScene(Scene, OpenSceneMode.Single);
        AppUIBuilder.BuildForPreview();
        EditorSceneManager.SaveOpenScenes();

        BuildPlayerOptions options = new BuildPlayerOptions
        {
            scenes = new[] { Scene },
            locationPathName = path,
            target = BuildTarget.Android,
            targetGroup = BuildTargetGroup.Android,
            options = BuildOptions.None
        };

        BuildReport report = BuildPipeline.BuildPlayer(options);
        BuildSummary summary = report.summary;

        if (summary.result == BuildResult.Succeeded)
        {
            Debug.Log("[Build] " + path + "  " +
                      (summary.totalSize / (1024 * 1024)) + " MB  in " +
                      Math.Round(summary.totalTime.TotalSeconds) + "s");
            return;
        }

        Debug.LogError("[Build] Failed: " + summary.result + ", " +
                       summary.totalErrors + " error(s)");

        // Batch mode reports success on exit code alone unless something fails the
        // process, so a failed build has to say so loudly enough to stop a script.
        EditorApplication.Exit(1);
    }
}
